<?php
namespace App\Services;
use App\Exceptions\ApiException;
use App\Models\{Branch,CustomerPayment,Expense,ExpensePayment,ExpenseReversal,ProductBatch,Sale,SaleDebt,SaleItem,SaleReturn,SaleReturnItem,User};
use App\Support\{Money,Quantity,ReportMath,ReportPeriod};
use Illuminate\Database\Eloquent\Builder;
use Illuminate\Support\Facades\DB;
class ReportService {
 public function receipt(User $original, Sale $sale): Sale {
  $sale->assertCurrentBusiness();
  return DB::transaction(function () use ($original, $sale) {
   $actor = app(FinancialActorService::class)->lock($original, 'view_reports');
   if (! $actor->hasRole('owner')) throw new \Illuminate\Auth\Access\AuthorizationException;
   return Sale::whereKey($sale->id)->firstOrFail();
  });
 }
 public function summary(array $filters):array{return DB::transaction(function()use($filters){$period=new ReportPeriod($filters['from'],$filters['to']);$branch=$this->branch($filters);$daily=[];for($day=\Carbon\CarbonImmutable::parse($period->from,'Africa/Dar_es_Salaam')->startOfDay();$day->toDateString()<=$period->to;$day=$day->addDay())$daily[$day->toDateString()]=['date'=>$day->toDateString(),'net_sales_gross'=>0];$v=array_fill_keys(['sale_count','sales_gross','sales_vat','refunds_gross','refunds_vat','cogs','returned_cogs','expenses','expense_reversals','cash_sales','mobile_sales','credit_sales','cash_collections','mobile_collections','cash_refunds','mobile_refunds','expense_payments','expense_refunds','supplier_payments','commission_accrual','commission_payouts','legacy_cost_allocations','stock_loss_cost'],0);$sales=$this->window(Sale::query(),$period);if($branch)$sales->where('branch_id',$branch->id);$this->bounded($sales);
  $sales->with(['items.batch','payments'])->chunkById(100,function($rows)use(&$v,&$daily){foreach($rows as$s){$date=($s->occurred_at??$s->created_at)->copy()->timezone('Africa/Dar_es_Salaam')->toDateString();$this->add($daily[$date],'net_sales_gross',$s->total);$this->add($v,'sale_count',1);$this->add($v,'sales_gross',$s->total);$this->add($v,'sales_vat',$s->vat_amount);foreach($s->payments as$p){$key=match($p->method){'cash'=>'cash_sales','mpesa'=>'mobile_sales','credit'=>'credit_sales'};$this->add($v,$key,(int)$p->amount);}foreach($s->items as$item){if($item->cost_price===null)$this->add($v,'legacy_cost_allocations',1);$this->add($v,'cogs',$this->cost($item,$s));}}});
  $returns=$this->window(SaleReturn::query(),$period);if($branch)$returns->whereIn('sale_id',Sale::where('branch_id',$branch->id)->select('id'));$this->bounded($returns);
  $returns->chunkById(100,function($rows)use(&$v,&$daily){foreach($rows as$r){$date=$r->created_at->copy()->timezone('Africa/Dar_es_Salaam')->toDateString();$this->add($daily[$date],'net_sales_gross',-$r->refund_total);$s=Sale::findOrFail($r->sale_id);$before=Money::amount(Quantity::parse((string)SaleReturn::where('sale_id',$s->id)->where('id','<',$r->id)->sum('refund_total')));$this->add($v,'refunds_gross',$r->refund_total);$this->add($v,'refunds_vat',ReportMath::reversal($s->vat_amount,$s->total,$before,$r->refund_total));$this->add($v,'cash_refunds',$r->cash_refund);$this->add($v,'mobile_refunds',$r->mobile_refund);SaleReturnItem::where('sale_return_id',$r->id)->chunkById(100,function($items)use(&$v,$s){foreach($items as$ri){$original=SaleItem::with('batch')->findOrFail($ri->sale_item_id);$before=Quantity::parse((string)SaleReturnItem::where('sale_item_id',$original->id)->where('id','<',$ri->id)->sum('qty_atoms'));$this->add($v,'returned_cogs',ReportMath::reversal($this->cost($original,$s),$original->qty_atoms,$before,$ri->qty_atoms));}});}});
  $collections=$this->window(CustomerPayment::query(),$period);if($branch)$collections->whereIn('till_session_id',\App\Models\TillSession::where('branch_id',$branch->id)->select('id'));$collections->chunkById(100,function($rows)use(&$v){foreach($rows as$p)$this->add($v,$p->method==='mpesa'?'mobile_collections':'cash_collections',$p->amount);});
  // Expense/supplier journals are business-wide; do not silently allocate them to one branch.
  if(!$branch){Expense::whereBetween('incurred_on',[$period->from,$period->to])->chunkById(100,function($rows)use(&$v){foreach($rows as$e)$this->add($v,'expenses',$e->amount);});ExpenseReversal::whereBetween('reversed_on',[$period->from,$period->to])->chunkById(100,function($rows)use(&$v){foreach($rows as$e)$this->add($v,'expense_reversals',$e->amount);});ExpensePayment::whereBetween('paid_on',[$period->from,$period->to])->chunkById(100,function($rows)use(&$v){foreach($rows as$e)$this->add($v,$e->kind==='refund'?'expense_refunds':'expense_payments',$e->amount);});\App\Models\SupplierPayment::whereBetween('paid_on',[$period->from,$period->to])->chunkById(100,function($rows)use(&$v){foreach($rows as$p)$this->add($v,'supplier_payments',$p->amount);});}
  if(!$branch){\App\Models\IncentiveEntry::where(function($q)use($period){$q->where(fn($e)=>$e->where('event_type','sale')->whereIn('incentive_account_id',\App\Models\IncentiveAccount::select('id')->whereIn('sale_id',$this->window(Sale::select('id'),$period))))->orWhere(fn($e)=>$this->window($e->where('event_type','!=','sale'),$period));})->chunkById(100,function($rows)use(&$v){foreach($rows as$entry)$this->add($v,'commission_accrual',$entry->commission_delta);});\App\Models\CommissionPayout::whereBetween('paid_on',[$period->from,$period->to])->chunkById(100,function($rows)use(&$v){foreach($rows as$payout)$this->add($v,'commission_payouts',$payout->amount);});}
  if(!$branch){$this->window(\App\Models\StockMovement::where('type','stock_loss'),$period)->chunkById(100,function($rows)use(&$v){foreach($rows as$movement)$this->add($v,'stock_loss_cost',$movement->receipt['loss_value']);});}
  $v['paid_sales']=$this->total([$v['cash_sales'],$v['mobile_sales']]);$v['net_sales_gross']=ReportMath::add($v['sales_gross'],-$v['refunds_gross']);$v['net_output_vat']=ReportMath::add($v['sales_vat'],-$v['refunds_vat']);$v['net_revenue']=ReportMath::add($v['net_sales_gross'],-$v['net_output_vat']);$v['net_cogs']=ReportMath::add($v['cogs'],-$v['returned_cogs']);$v['gross_profit']=ReportMath::add($v['net_revenue'],-$v['net_cogs']);$v['net_expenses']=ReportMath::add($v['expenses'],-$v['expense_reversals']);$v['profit_before_commissions']=ReportMath::add(ReportMath::add($v['gross_profit'],-$v['net_expenses']),-$v['stock_loss_cost']);$v['net_profit']=ReportMath::add($v['profit_before_commissions'],-$v['commission_accrual']);$in=$this->total([$v['cash_sales'],$v['mobile_sales'],$v['cash_collections'],$v['mobile_collections'],$v['expense_refunds']]);$out=$this->total([$v['cash_refunds'],$v['mobile_refunds'],$v['expense_payments'],$v['supplier_payments'],$v['commission_payouts']]);$v['cashflow_in']=$in;$v['cashflow_out']=$out;$v['net_cashflow']=ReportMath::add($in,-$out);
  return ['period'=>['from'=>$period->from,'to'=>$period->to,'timezone'=>'Africa/Dar_es_Salaam','branch_id'=>$branch?->publicId()],'summary'=>$v,'daily'=>array_values($daily),'generated_at'=>now()->toISOString(),'basis'=>'event_date_accrual','scope'=> $branch?'branch_sales_only':'business','tax_basis'=>'stored_output_vat_bookkeeping','stock'=>$this->stockTotals(),'outstanding_customer_debt'=>$this->debtBalance()];
 });}
 public function sales(array $filters){$p=new ReportPeriod($filters['from'],$filters['to']);$q=$this->window(Sale::with(['payments','branch','cashier']),$p);if($branch=$this->branch($filters))$q->where('branch_id',$branch->id);$rows=$q->orderByRaw('COALESCE(occurred_at,created_at) DESC')->orderByDesc('id')->paginate($filters['per_page']??50);return ['rows'=>array_map(fn($s)=>['id'=>$s->publicId(),'receipt_number'=>$s->receipt_number,'created_at'=>($s->occurred_at??$s->created_at)->toISOString(),'branch'=>$s->branch->name,'cashier'=>$s->cashier->name,'total'=>$s->total,'vat_amount'=>$s->vat_amount,'net_revenue'=>$s->total-$s->vat_amount],$rows->items()),'meta'=>['page'=>$rows->currentPage(),'per_page'=>$rows->perPage(),'total'=>$rows->total()]];}
 public function stock(array $filters){$rows=ProductBatch::with('product')->orderBy('product_id')->orderBy('id')->paginate($filters['per_page']??50);return ['rows'=>array_map(fn($b)=>['id'=>$b->publicId(),'product_name'=>$b->product->name,'batch_number'=>$b->batch_number,'qty'=>Quantity::format($b->qty_remaining_atoms,$b->product->quantity_type==='weight'),'unit'=>$b->product->unit,'cost_price'=>$b->cost_price,'value'=>$b->qty_remaining_atoms>0?Money::lineTotal($b->qty_remaining_atoms,$b->cost_price,$b->product->quantity_type==='weight'):0,'status'=>$this->stockStatus($b),'expiry_date'=>$b->expiry_date?->format('Y-m-d')],$rows->items()),'meta'=>['page'=>$rows->currentPage(),'per_page'=>$rows->perPage(),'total'=>$rows->total()],'as_of'=>now()->toISOString()];}
 private function stockTotals():array{$v=['recorded_value'=>0,'sellable_value'=>0,'held_value'=>0,'negative_batches'=>0];ProductBatch::with('product')->chunkById(100,function($rows)use(&$v){foreach($rows as$b){if($b->qty_remaining_atoms<0){$this->add($v,'negative_batches',1);continue;}$value=Money::lineTotal($b->qty_remaining_atoms,$b->cost_price,$b->product->quantity_type==='weight');$this->add($v,'recorded_value',$value);$this->add($v,$this->stockStatus($b)==='sellable'?'sellable_value':'held_value',$value);}});return $v;}
 private function stockStatus(ProductBatch $b):string{if($b->qty_remaining_atoms<0)return 'negative_conflict';if(!$b->product->is_active||$b->product->trashed())return 'inactive';if($b->is_quarantined||$b->is_recalled)return 'held';if($b->expiry_date&&$b->expiry_date->format('Y-m-d')<now('Africa/Dar_es_Salaam')->format('Y-m-d'))return 'expired';return 'sellable';}
 private function cost(SaleItem $i,Sale $s):int{$weighted=($s->lines[$i->line_index]['quantity_type']??null)==='weight';return Money::lineTotal($i->qty_atoms,$i->cost_price??$i->batch->cost_price,$weighted);}
 private function debtBalance():int{$n=0;SaleDebt::where('remaining_amount','>',0)->chunkById(100,function($rows)use(&$n){foreach($rows as$d)$n=ReportMath::add($n,$d->remaining_amount);});return $n;}
 private function branch(array $f):?Branch{return isset($f['branch_id'])?(new Branch)->resolveRouteBindingQuery(Branch::query(),$f['branch_id'])->firstOrFail():null;}
 private function window(Builder $q,ReportPeriod $p):Builder{if($q->getModel() instanceof Sale)return $q->where(fn($inner)=>$inner->where(fn($a)=>$a->where('occurred_at','>=',$p->start)->where('occurred_at','<',$p->until))->orWhere(fn($a)=>$a->whereNull('occurred_at')->where('created_at','>=',$p->start)->where('created_at','<',$p->until)));return $q->where('created_at','>=',$p->start)->where('created_at','<',$p->until);}
 private function bounded(Builder $q):void{if((clone $q)->limit(10001)->get(['id'])->count()>10000)throw new ApiException('REPORT_TOO_LARGE','Choose a narrower report period.',422);}
 private function add(array &$v,string $k,int $n):void{$v[$k]=ReportMath::add($v[$k],$n);}
 private function total(array $values):int{$v=0;foreach($values as$n)$v=ReportMath::add($v,$n);return $v;}
}

